'use strict';

function lastN(arr, n) {
  // Off-by-one: should be slice(arr.length - n), not slice(arr.length - n - 1)
  return arr.slice(arr.length - n - 1);
}

function divide(a, b) {
  // Missing zero-check
  return a / b;
}

function parseUserId(raw) {
  // No type check; passes NaN through silently
  return parseInt(raw, 10);
}

module.exports = { lastN, divide, parseUserId };
